functions.pickAnswer:
function pickAnswer(value: number) {
    if (answerLock.current) return;
    answerLock.current = true;
    setTransitioning(true);
    tracking.answer(answers.filter(answer => answer >= 0).length + (answers[index] < 0 ? 1 : 0), index + 1);
    setAnswers((previous) => {
      const next = [...previous];
      next[index] = value;
      return next;
    });

    answerTimer.current = setTimeout(() => {
    if (!unlocked && !isFinished && answers.every((answer, i) => i === index || answer >= 0)) setAnalysisStep(0);
      if (index < totalQuestions - 1) {
        setIndex((currentIndex) => currentIndex + 1);
      }
      answerLock.current = false;
      setTransitioning(false);
      answerTimer.current = null;
    }, 220);
  }

functions.restart:
function restart() {
    tracking.restart();
    setAnalysisStep(null);
    setAnswers(Array(totalQuestions).fill(-1));
    setIndex(0);
    setUnlocked(hasPaidReturn(LS_KEY));

    try {
      localStorage.removeItem(LS_KEY);
    } catch {
      // ignore
    }

    window.scrollTo({ top: 0, behavior: "smooth" });
  }

functions.goToCheckout:
function goToCheckout() {
    if (!CHECKOUT_URL) {
      alert(
        "Betalningslänken för anknytningstestet kopplas in efter att testet verifierats."
      );
      return;
    }

    if (!payment.prepareCheckout({ index, answers, unlocked })) return;
    tracking.checkout(() => { window.location.href = CHECKOUT_URL; });
  }

effects:
useEffect(() => {
    if (!analyzing) return;
    const second = setTimeout(() => setAnalysisStep(1), 1000);
    const third = setTimeout(() => setAnalysisStep(2), 2000);
    const finish = setTimeout(() => setAnalysisStep(null), 3000);
    return () => { clearTimeout(second); clearTimeout(third); clearTimeout(finish); };
  }, [analyzing])

useEffect(() => {
    try {
      const raw = localStorage.getItem(LS_KEY);

      if (raw) {
        const parsed = JSON.parse(raw) as {
          index?: number;
          answers?: number[];
        };

        if (
          Array.isArray(parsed.answers) &&
          parsed.answers.length === totalQuestions
        ) {
          setAnswers(parsed.answers);
        }

        if (typeof parsed.index === "number") {
          setIndex(clamp(parsed.index, 0, totalQuestions - 1));
        }
      }
    } catch {
      // Testet fungerar även utan sparad lokal data.
    }

    setHydrated(true);
  }, [totalQuestions])

useEffect(() => {
    if (!hydrated) return;

    try {
      localStorage.setItem(
        LS_KEY,
        JSON.stringify({
          index,
          answers,
        })
      );
    } catch {
      // Ignorera om localStorage är blockerat.
    }
  }, [index, answers, hydrated])

useEffect(() => {
    const params = new URLSearchParams(window.location.search);

    if (params.get("paid") === "true") {
      tracking.purchase();
      setUnlocked(true);
      window.history.replaceState({}, "", window.location.pathname);
      window.scrollTo({ top: 0, behavior: "smooth" });
    }
  }, [])

medberoendetest.scoreBody:
{
    const raw = {} as Record<Area, number>;
    const maximum = {} as Record<Area, number>;

    (Object.keys(areaLabels) as Area[]).forEach((area) => {
      raw[area] = 0;
      maximum[area] = 0;
    });

    questions.forEach((question, questionIndex) => {
      maximum[question.area] += 4;

      const answer = answers[questionIndex];

      if (answer >= 0) {
        raw[question.area] += answer;
      }
    });

    const areas = {} as Record<Area, number>;

    (Object.keys(areaLabels) as Area[]).forEach((area) => {
      areas[area] =
        maximum[area] > 0
          ? Math.round((raw[area] / maximum[area]) * 100)
          : 0;
    });

    const overall =
      Math.round(
        (Object.values(areas).reduce((sum, score) => sum + score, 0) /
          Object.values(areas).length) *
          10
      ) / 10;

    return {
      areas,
      overall,
    };
  }

